from ortools.sat.python import cp_model
import json

# Input data
X = -1
game_data = [  # 0-8: number of mines around, -1: not opened
    [2, 3, X, 2, 2, X, 2, 1],
    [X, X, 4, X, X, 4, X, 2],
    [X, X, X, X, X, X, 4, X],
    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
]

# Model definition
model = cp_model.CpModel()

rows = len(game_data)
cols = len(game_data[0]) if rows > 0 else 0

# Decision Variables: mines[row][col] is 1 if it's a mine, 0 otherwise
mines = []
for r in range(rows):
    mine_row = []
    for c in range(cols):
        if game_data[r][c] == X:
            mine_row.append(model.NewBoolVar(f'mine_{r}_{c}'))
        else:
            mine_row.append(None)  # Not a variable, just placeholder
    mines.append(mine_row)

# Constraints
for r in range(rows):
    for c in range(cols):
        if game_data[r][c] != X and game_data[r][c] >= 0:
            # Collect adjacent cells (8 directions)
            adjacent_mines = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue  # Skip the cell itself
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and game_data[nr][nc] == X:
                        adjacent_mines.append(mines[nr][nc])
            # The sum of adjacent mines must equal the clue
            model.Add(sum(adjacent_mines) == game_data[r][c])

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    # Prepare the solution: 1 if mine, 0 otherwise
    solution_mines = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if game_data[r][c] == X:
                row.append(int(solver.Value(mines[r][c])))
            else:
                row.append(0)  # Not a mine (known cell)
        solution_mines.append(row)
    solution = {'mines': solution_mines}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

