from ortools.sat.python import cp_model
import json

# Input data
N = 20
puzzle_start = [
    [0, 3, 6],
    [2, 4, 8],
    [1, 7, 5]
]
puzzle_end = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 0]
]

rows = len(puzzle_start)
cols = len(puzzle_start[0])

# Model definition
model = cp_model.CpModel()

# Decision Variables
# steps[t][i][j] represents the value at position (i,j) at step t
steps = {}
for t in range(N + 1):
    for i in range(rows):
        for j in range(cols):
            steps[(t, i, j)] = model.NewIntVar(0, 8, f'step_{t}_{i}_{j}')

# Constraints
# Initial state constraint
for i in range(rows):
    for j in range(cols):
        model.Add(steps[(0, i, j)] == puzzle_start[i][j])

# Final state constraint
for i in range(rows):
    for j in range(cols):
        model.Add(steps[(N, i, j)] == puzzle_end[i][j])

# Transition constraints between steps
for t in range(N):
    # The empty tile (0) must move to an adjacent position
    # Find the position of the empty tile at step t
    empty_pos_t = []
    for i in range(rows):
        for j in range(cols):
            empty_pos_t.append((i, j, steps[(t, i, j)] == 0))

    # Only one empty tile
    model.AddExactlyOne([cond for (i, j, cond) in empty_pos_t])

    # For each step, the empty tile can move to adjacent positions
    for i in range(rows):
        for j in range(cols):
            # Check if (i,j) is the empty tile at step t
            is_empty = steps[(t, i, j)] == 0

            # Possible moves: up, down, left, right
            moves = []
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < rows and 0 <= nj < cols:
                    # The tile at (ni, nj) moves to (i, j)
                    moves.append(steps[(t + 1, i, j)] == steps[(t, ni, nj)])

            # If (i,j) is empty at step t, then at step t+1 it must be one of the adjacent tiles
            model.AddImplication(is_empty, cp_model.LinearExpr.Sum(moves) >= 1)

            # Non-empty tiles can only change if they are adjacent to the empty tile
            not_empty = steps[(t, i, j)] != 0
            same_value = steps[(t + 1, i, j)] == steps[(t, i, j)]
            model.AddImplication(not_empty, same_value)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'steps': [
            [
                [solver.Value(steps[(t, i, j)]) for j in range(cols)]
                for i in range(rows)
            ]
            for t in range(N + 1)
        ]
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
